gag6(){return"\u0646\u0634\u0637"},
gaeT(){return"\u0627\u0644\u0627\u0633\u0645"},
gaeS(){return"\u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0643\u0648\u0651\u0646\u0629"},
